data={'question':'Where does current Ferroni spend time on simple shared-syntax regular expressions?', 'commit':cap(['git','rev-parse','HEAD']),'source_state':cap(['git','status','--porcelain']),'start_utc':utc(),'rustc':cap(['rustc','-vV']),'samply':cap(['samply','--version']),'os':cap(['sw_vers']),'hardware':cap(['sysctl','machdep.cpu.brand_string','hw.memsize','hw.ncpu']),'binary_sha256':sha(BIN),'build':'FERRONI_ONIGURUMA_DIR=<pinned C checkout> cargo bench --locked --features ffi --bench battle_bench --no-run','features':['ffi'],'match_cache':False,'target':'portable','lto':'thin','debug_info':'default bench profile; executable symbols used','source_sha256':{f:sha(ROOT/f) for f in ['Cargo.toml','Cargo.lock','benches/battle_bench.rs','benches/general_regex.rs','benches/battle_inputs.toml','src/regexec.rs']},'coordination':'Exclusive CPU gate for the complete smoke/profile series. No concurrent task builds, tests, or benchmark runs. Desktop activity uncontrolled.','runner_source':pathlib.Path(__file__).read_text(),'profiles':[]}
smoke=subprocess.run([str(BIN),'--test'],cwd=OUT,env=ENV,capture_output=True,text=True,timeout=60); (OUT/'smoke.log').write_text(smoke.stdout+smoke.stderr); assert smoke.returncode==0,smoke.stderr[-2000:]
