 row={'case':case,'command':cmd,'start_utc':utc(),'load_average':os.getloadavg()}; start=time.monotonic()
 r=subprocess.run(cmd,cwd=OUT,env=ENV,capture_output=True,text=True,timeout=60); (OUT/(name+'.log')).write_text(r.stdout+r.stderr); row.update(exit=r.returncode,elapsed_seconds=time.monotonic()-start); assert r.returncode==0,(case,r.stderr[-2000:])
