 (OUT/'metadata.json').write_text(json.dumps(data,indent=2)+'\n')
 summary=cap(['python3','/tmp/ferroni-profile-summary.py',str(path)]); (OUT/(name+'-summary.txt')).write_text(summary); print(case+'\n'+summary,flush=True)
data['end_utc']=utc(); (OUT/'metadata.json').write_text(json.dumps(data,indent=2)+'\n'); print('COMPLETE',OUT,flush=True)
